procedure CoffeeReorder {
  about "Reorder coffee below their minimum"
  policy CoffeePolicy
  sheet Beans "Beans" { blend: Text, bags: Number, reorder_at: Number, order_bags: Number, roaster: Text, price_per_bag: Money }
  trigger every day at 06:30

  let all = fetch Beans
  let low = filter all where bags <= reorder_at
  for each i in low up to 2 {
    let cost = i.order_bags * i.price_per_bag
    if cost > $120.00 {
      notify owner "Reorder of {i.blend} would cost {cost}, over the $120 limit."
      skip
    }
    order "{i.order_bags} x {i.blend}" from i.roaster cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.blend}"
  }
}
