procedure IceReorder {
  about "Reorder ice below their minimum"
  policy IcePolicy
  sheet Flavors "Flavors" { flavor: Text, tubs: Number, minimum: Number, reorder_tubs: Number, supplier: Text, tub_cost: Money }
  trigger every day at 07:00

  let all = fetch Flavors
  let low = filter all where tubs < minimum
  for each i in low up to 4 {
    let cost = i.reorder_tubs * i.tub_cost
    if cost > $150.00 {
      notify owner "Reorder of {i.flavor} would cost {cost}, over the $150 limit."
      skip
    }
    order "{i.reorder_tubs} x {i.flavor}" from i.supplier cost cost, ask owner first timeout 1 day else skip
    log "ordered {i.flavor}"
  }
}
